"use client";

import * as React from "react";
import {
  Area,
  Bar,
  CartesianGrid,
  ComposedChart as RechartsComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  AnimatedDashedStroke,
  AreaFillDefs,
  BarFillDefs,
  type BarFillVariant,
  ChartActiveDot,
  type ChartDatum,
  ChartFrame,
  ChartGlowFilter,
  chartGrid,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  ChartRestingDot,
  type ChartSeries,
  ChartTooltipContent,
  chartXAxis,
  chartYAxis,
  type ChartDotRenderProps,
  compactFormatValue,
  RevealMask,
  areaFillUrl,
  barFillUrl,
  createGrowBarShape,
  HoverIndexProvider,
  readActiveTooltipIndex,
  resolveSeries,
  type StrokeVariant,
  strokeDasharray,
  useChartId,
  useChartMotion,
  useIntroStartedAt,
} from "@/components/moneytrees/charts/chart-kit";

const BAR_RADIUS = [4, 4, 0, 0] as [number, number, number, number];

export type ComposedMark = "bar" | "line" | "area";
export type ComposedSeries = ChartSeries & { mark?: ComposedMark };

export interface SpectrumComposedChartProps {
  className?: string;
  data: ChartDatum[];
  xKey: string;
  /** First series defaults to bars, the rest to lines. */
  series: ComposedSeries[];
  barVariant?: BarFillVariant;
  lineStroke?: StrokeVariant;
  lineCurve?: "monotone" | "bump" | "step";
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  showGrid?: boolean;
  height?: number;
  formatX?: (value: string | number) => string;
  formatValue?: (value: number) => string;
}

export function ComposedChart({
  className,
  data,
  xKey,
  series,
  barVariant = "default",
  lineStroke = "solid",
  lineCurve = "monotone",
  glowing = false,
  isLoading = false,
  showLegend = true,
  showGrid = true,
  height,
  formatX,
  formatValue,
}: SpectrumComposedChartProps) {
  const id = useChartId("composed");
  const { reduce } = useChartMotion();
  const introStartedAt = useIntroStartedAt();
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);
  const marks = resolveSeries(series).map((s, i) => ({
    ...s,
    mark: series[i]?.mark ?? (i === 0 ? "bar" : "line"),
  }));
  const glowId = `${id}-glow`;
  const maskId = `${id}-reveal`;
  const maskStyle = reduce ? undefined : { mask: `url(#${maskId})` };

  const barShape = React.useMemo(
    () =>
      createGrowBarShape({
        introStartedAt,
        dataLength: data.length,
        reduce,
        radius: BAR_RADIUS,
        stripped: barVariant === "stripped",
        glowId: glowing ? glowId : undefined,
      }),
    [introStartedAt, data.length, reduce, barVariant, glowing, glowId],
  );

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && marks.length > 1 ? <ChartLegend items={marks} /> : null}
      {isLoading ? (
        <ChartLoadingBars />
      ) : (
        <ChartPlotSurface>
          <HoverIndexProvider value={activeIndex}>
            <ResponsiveContainer width="100%" height="100%">
              <RechartsComposedChart
                data={data}
                margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
                onMouseMove={(state) => {
                  const next = readActiveTooltipIndex(state);
                  setActiveIndex((current) => (current === next ? current : next));
                }}
                onMouseLeave={() => setActiveIndex(null)}
              >
                <defs>
                  {marks.map((s) =>
                    s.mark === "bar" ? (
                      <BarFillDefs
                        key={s.key}
                        id={`${id}-${s.key}`}
                        color={s.color}
                        variant={barVariant}
                      />
                    ) : s.mark === "area" ? (
                      <AreaFillDefs
                        key={s.key}
                        id={`${id}-${s.key}`}
                        color={s.color}
                        variant="gradient"
                      />
                    ) : null,
                  )}
                  {glowing ? <ChartGlowFilter id={glowId} /> : null}
                  <RevealMask id={maskId} introStartedAt={introStartedAt} reduce={reduce} />
                </defs>
                {showGrid ? <CartesianGrid {...chartGrid} /> : null}
                <XAxis {...chartXAxis} dataKey={xKey} tickFormatter={formatX} />
                <YAxis {...chartYAxis} tickFormatter={formatValue ?? compactFormatValue} />
                <Tooltip
                  cursor={{ fill: "currentColor", fillOpacity: 0.05 }}
                  content={<ChartTooltipContent formatValue={formatValue} formatLabel={formatX} />}
                />
                {marks.map((s) => {
                  if (s.mark === "area") {
                    return (
                      <Area
                        key={s.key}
                        type={lineCurve}
                        dataKey={s.key}
                        name={s.label}
                        stroke={s.color}
                        strokeWidth={1.5}
                        fill={areaFillUrl(`${id}-${s.key}`, "gradient", s.color)}
                        isAnimationActive={false}
                        style={maskStyle}
                      />
                    );
                  }
                  if (s.mark === "bar") {
                    return (
                      <Bar
                        key={s.key}
                        dataKey={s.key}
                        name={s.label}
                        fill={barFillUrl(`${id}-${s.key}`, barVariant, s.color)}
                        radius={BAR_RADIUS}
                        maxBarSize={28}
                        isAnimationActive={false}
                        shape={barShape}
                      />
                    );
                  }
                  return (
                    <Line
                      key={s.key}
                      type={lineCurve}
                      dataKey={s.key}
                      name={s.label}
                      stroke={s.color}
                      strokeWidth={2.25}
                      strokeDasharray={strokeDasharray(lineStroke)}
                      dot={
                        data.length <= 40
                          ? (props: ChartDotRenderProps) => (
                              <ChartRestingDot
                                key={`dot-${props.index}`}
                                cx={props.cx}
                                cy={props.cy}
                                color={s.color}
                                maskId={reduce ? undefined : maskId}
                              />
                            )
                          : false
                      }
                      activeDot={(props: ChartDotRenderProps) => (
                        <ChartActiveDot
                          key={`active-${props.index}`}
                          cx={props.cx}
                          cy={props.cy}
                          color={s.color}
                        />
                      )}
                      isAnimationActive={false}
                      style={maskStyle}
                    >
                      {lineStroke === "animated-dashed" ? <AnimatedDashedStroke /> : null}
                    </Line>
                  );
                })}
              </RechartsComposedChart>
            </ResponsiveContainer>
          </HoverIndexProvider>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
